class Solution {
    public String rankTeams(String[] votes){
        int size=votes[0].length();
        int[][] count=new int[26][size];
        for(String vote:votes)for(int i=0;i<size;i++)count[vote.charAt(i)-'A'][i]++;
        Character[] teams=new Character[size];
        for(int i=0;i<size;i++)teams[i]=votes[0].charAt(i);
        Arrays.sort(teams,(a,b)->{
            for(int i=0;i<size;i++){
                int difference=count[b-'A'][i]-count[a-'A'][i];
                if(difference!=0)return difference;
            }
            return Character.compare(a,b);
        });
        StringBuilder answer=new StringBuilder();
        for(char team:teams)answer.append(team);
        return answer.toString();
    }
}

code.kotlin:
class Solution {
    fun rankTeams(votes:Array<String>):String{
        val size=votes[0].length;
        val count=Array(26){
            IntArray(size)
        };
        for(vote in votes)for(i in 0 until size)count[vote[i]-'A'][i]++;
        return votes[0].toList().sortedWith(Comparator{
            a,b->for(i in 0 until size){
                val difference=count[b-'A'][i]-count[a-'A'][i];
                if(difference!=0)return@Comparator difference
            };
            a.compareTo(b)
        }).joinToString("")
    }
}

